package main

import (
	"context"
	"fmt"
	"log"

	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/ec2"
)

func main() {
	// Create an AWS session
	sess, err := session.NewSession(&aws.Config{Region: aws.String("your-region")}, nil)
	if err != nil {
		log.Fatal(err)
	}

	// Create an EC2 client
	ec2client := ec2.New(sess)

	// Define the retention policy
	retentionPolicy := map[string]int{
		"monthly": 14,
		"daily":   10,
		"weekly":  4,
		"yearly":  1,
	}

	// Get all snapshots with the specified tag
	input := &ec2.DescribeSnapshotsInput{Filters: []*ec2.Filter{
		{
			Name: aws.String("tag:backup_type"),
			Values: []*string{
				aws.String("monthly"),
				aws.String("daily"),
				aws.String("weekly"),
				aws.String("yearly"),
			},
		},
	}}
	describeSnapshotsOutput, err := ec2client.DescribeSnapshots(input)
	if err != nil {
		log.Fatal(err)
	}

	// Iterate through the snapshots and delete the ones that exceed the retention policy
	log.Println("Deleting snapshots that exceed retention policy...")
	for _, snapshot := range describeSnapshotsOutput.Snapshots {
		snapshotId := aws.StringValue(snapshot.SnapshotId)
		tagValue, ok := snapshot.Tags map[string]*string{"backup_type"}
		if !ok {
			continue
		}
		tagValue := aws.StringValue(tagValue)

		// Calculate the number of snapshots to keep based on the retention policy
		var numToKeep int
		switch tagValue {
		case "monthly":
			numToKeep = retentionPolicy["monthly"]
		case "daily":
			numToKeep = retentionPolicy["daily"]
		case "weekly":
			numToKeep = retentionPolicy["weekly"]
		case "yearly":
			numToKeep = retentionPolicy["yearly"]
		}

		// Get the snapshots with the same tag value and sort them by creation time
		var snapshotIds []string
		for _, s := range describeSnapshotsOutput.Snapshots {
			if aws.StringValue(s.Tags["backup_type"]) == tagValue {
				snapshotIds = append(snapshotIds, aws.StringValue(s.SnapshotId))
			}
		}
		sortedSnapshotIds := sortSnapshotIds(snapshotIds)

		// Delete the snapshots that exceed the retention policy
		deleted := 0
		for i, id := range sortedSnapshotIds {
			if i >= numToKeep {
				_, err = ec2client.DeleteSnapshot(&ec2.DeleteSnapshotInput{SnapshotId: aws.String(id)})
				if err != nil {
					log.Fatal(err)
				}
				deleted++
			} else {
				break
			}
		}
		log.Printf("Deleted %d snapshots with backup type %s\n", deleted, tagValue)
	}
}

func sortSnapshotIds(ids []string) []string {
	sort.SliceStable(ids, func(i, j int) bool {
		return aws.StringValue(ec2client.DescribeSnapshotsOutput.Snapshots[i].{},
			"CreateTime").before(aws.StringValue(ec2client.DescribeSnapshotsOutput.Snapshots[j].{},
			"CreateTime"))
	})
	return ids
}
```
