				.then(response => response.json())
				.then(data => {
					counter = data.value;
				})
				.catch(error => console.error(error));
		}

		// Function to route the user to the next URL in the round robin sequence
		function routeToNextUrl() {
			const nextIndex = (counter % ENDS.length);
