package main

import (
	"path/filepath"

	. "github.com gratedtech/Terratest/v2"
)

func main() {
	Run(&Require{
		Steps: []Step{
			&StepTerraform{
				.Path: filepath.Join(os.Getenv("TERRAFORM_DIR"), "main.tf"),
				StatePath: filepath.Join(os.Getenv("TERRAFORM_DIR"), "terraform.tfstate"),
			},
			&StepBash{
				Cmd: []string{
					"terraform", "apply",
					"-input=false",
					"-auto-approve",
				},
			},
			&StepAzure{
				SubscriptionID: "your_subscription_id",
				RESOURCEGROUP:  "your_resource_group",
				NAME:           "your_web_app",
				ContainerName:  "your_container_name",
			},
		},
	})
}

type StepTerraform struct {
	Path    string
	StatePath string
}

func (st *StepTerraform) Skip() bool {
	return false
}

func (st *StepTerraform) Run(context.Context) error {
	cmd := exec.Command("terraform", "init")
	cmd.Dir = st.Path
	if err := cmd.Run(); err != nil {
		return err
	}
	cmd = exec.Command("terraform", "apply", "-input=false", "-auto-approve")
	cmd.Dir = st.Path
	return cmd.Run()
}

type StepBash struct {
	Cmd []string
}

func (sb *StepBash) Skip() bool {
	return false
}

func (sb *StepBash) Run(context.Context) error {
	cmd := exec.Command(sb.Cmd[0], sb.Cmd[1:]...)
	return cmd.Run()
}

type StepAzure struct {
	SubscriptionID  string
	RESOURCEGROUP  string
	NAME           string
	ContainerName string
}

func (sa *StepAzure) Skip() bool {
	return false
}

func (sa *StepAzure) Run(context.Context) error {
	// Use Azure CLI to check if the container is running
	cmd := exec.Command("az", "webapp", "container", "show", sa.NAME, "--resource-group", sa.RESOURCEGROUP)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return err
	}
	if bytes.Contains(output, []byte("running")) {
		return nil
	}
	return fmt.Errorf("container %s is not running", sa.ContainerName)
}
```
