#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <algorithm>

using namespace std;

int main(int argc, char** argv) {
    if (argc != 3) {
        cout << "Usage: " << argv[0] << " <input_file> <output_file>" << endl;
        return 1;
    }

    string input_file = argv[1];
    string output_file = argv[2];

    ifstream input(input_file, ios::binary);
    if (!input) {
        cerr << "Error opening input file " << input_file << endl;
        return 1;
    }

    ofstream output(output_file, ios::out | ios::binary);
    if (!output) {
        cerr << "Error opening output file " << output_file << endl;
        return 1;
    }

    char buffer[4096];
    while (true) {
        input.read(buffer, 4096);
        if (input.gcount() == 0) break;

        for (int i = 0; i < input.gcount(); i++) {
            if (input.tellg() == 0x2D32CC && buffer[i] == 0x75) {
                buffer[i] = 0xEB;
            } else if (input.tellg() == 0x2D32CD && buffer[i] == 0x47) {
                buffer[i] = 0x42;
            }
        }

        output.write(buffer, input.gcount());
    }

    input.close();
    output.close();

    cout << "Patched bytes successfully!" << endl;
    return 0;
}
