let score = 0;
let correctAnswers = 0;
let questionsAsked = 0;
let colorScheme = "good";
let quotes = [
	"'Believe you can and you're halfway there.' - Theodore Roosevelt",
	"'Excellence is not a destination; it is a continuous journey.' - Brian Tracy",
	"'Success is not final, failure is not fatal: It is the courage to continue that counts.' - Winston Churchill",
	"'Don't watch the clock; do what it does. Keep going.' - Sam Levenson",
	"'You miss 100% of the shots you don't take.' - Wayne Gretzky"
];

function generateQuestion() {
	const num1 = Math.floor(Math.random() * 10) + 1;
	const num2 = Math.floor(Math.random() * 10) + 1;
	const operator = Math.random() < 0.5 ? "+" : "-";
	const answer = eval(num1 + operator + num2);
	const question = `${num1} ${operator} ${num2}`;
	return { question, answer };
}

function checkAnswer() {
	const userAnswer = parseInt(document.getElementById("answer").value, 10);
	const questionAnswer = generateQuestion().answer;
	if (userAnswer === questionAnswer) {
		document.getElementById("message").textContent = "Correct!";
		document.getElementById("message").style.color = "green";
		score++;
		correctAnswers++;
		colorScheme = "good";
		document.getElementById("game-container").classList.add("good");
		document.getElementById("quote-container").textContent = quotes[Math.floor(Math.random() * quotes.length)];
	} else {
		document.getElementById("message").textContent = "Incorrect. Try again!";
		document.getElementById("message").style.color = "red";
		colorScheme = "bad";
		document.getElementById("game-container").classList.add("bad");
	}
}

function gameOver() {
	document.getElementById("header").textContent = "Game Over!";
	document.getElementById("question").textContent = "Your score is " + score + " out of 10";
	document.getElementById("quote-container").textContent = "Keep practicing!";
	setTimeout(() => {
		document.getElementById("game-container").classList.add("good");
	}, 1000);
	setTimeout(() => {
		document.getElementById("game-container").classList.remove("good", "bad");
